// Runs before the Netlify build. Copies the site's public Supabase address and public
// ("anon") key into a small file the edge functions can import. These two values are
// public by design: they are already in the website's own code.
// The generated file is not committed (see .gitignore).
import { writeFileSync } from 'node:fs';

const url = process.env.VITE_SUPABASE_URL ?? '';
const key = process.env.VITE_SUPABASE_ANON_KEY ?? '';

writeFileSync(
  new URL('../netlify/edge-functions/lib/config.ts', import.meta.url),
  `// Generated by scripts/write-edge-config.mjs. Do not edit.\nexport const SUPABASE_URL = ${JSON.stringify(url)};\nexport const SUPABASE_ANON_KEY = ${JSON.stringify(key)};\n`,
);

console.log(url ? 'Edge config written.' : 'Edge config written without a database address (link previews will use page defaults).');
